// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 0, 10 ether);
        vm.assume(actor != address(0));
        vm.deal(actor, amount);

        uint256 beforeBal = c.balances(actor);
        uint256 deposit = c.MinDeposit();

        bool ok;
        vm.prank(actor);
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterBal = c.balances(actor);

        assertTrue(
            !(ok && amount >= deposit) || afterBal == beforeBal + amount
        );
    }
}
